pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber, uint256 timestamp) public {
        vm.assume(timestamp > 0);
        vm.assume(blockNumber < 2**256 - 1);
        vm.warp(1);
        vm.deal(address(this), 10 ether);
        (bool ok0, ) = address(c).call{value: 10 ether}("");
        require(ok0, "initial call failed");
        vm.roll(blockNumber);
        vm.warp(timestamp);
        vm.assume(timestamp > c.pastBlockTime());
        uint256 balanceBefore = address(c).balance;
        address caller = address(0x1234);
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "call failed");
        if (blockNumber % 15 == 0) {
            assertEq(address(c).balance, 0);
        }
    }
}
